drop view if exists public.my_properties; create view public.my_properties as select o.id as order_id,o.user_id,o.customer_email,o.total_amount,o.amount_paid,o.balance,o.payment_status,o.created_at,i.property_id as item_property_id,i.plot_id,i.property_name,i.property_type,i.quantity,i.price as unit_price,dt.id as documentation_type_id,dt.name as documentation_name,dt.price as documentation_price,coalesce(edp.status,'unpaid') as documentation_payment_status,edp.amount as documentation_amount_paid,edp.reference as documentation_payment_reference from public.orders o cross join lateral jsonb_to_recordset(coalesce(o.items,'[]'::jsonb)) i(property_id text,plot_id text,property_name text,property_type text,quantity integer,price numeric) left join public.estate_subscriptions es on es.order_id=o.id left join public.documentation_types dt on true left join lateral (select e.* from public.estate_documentation_payments e where e.user_id=o.user_id and (e.estate_id=es.estate_id or e.reference=o.payment_reference) order by e.created_at desc limit 1) edp on true where o.user_id=auth.uid() and (coalesce(o.amount_paid,0)>0 or o.payment_status in ('paid','completed','awaiting_approval')); create or replace function public.create_documentation_payment_request(_order_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.orders; es public.estate_subscriptions; dt public.documentation_types; existing public.estate_documentation_payments; begin select * into o from public.orders where id=_order_id and user_id=auth.uid(); if not found then raise exception 'Order not found'; end if; select * into es from public.estate_subscriptions where order_id=_order_id and user_id=auth.uid() order by created_at desc limit 1; if es.estate_id is null then raise exception 'Estate subscription not found'; end if; select * into dt from public.documentation_types where price is not null and price>0 order by created_at asc limit 1; if dt.id is null then raise exception 'Documentation price has not been configured'; end if; select * into existing from public.estate_documentation_payments where user_id=auth.uid() and estate_id=es.estate_id and documentation_type_id=dt.id and status in ('pending','approved','paid','completed') order by created_at desc limit 1; if existing.id is not null then return jsonb_build_object('payment_id',existing.id,'amount',existing.amount,'status',existing.status,'reference',existing.reference,'already_created',true); end if; insert into public.estate_documentation_payments(user_id,estate_id,documentation_type_id,amount,status,is_bundle,reference) values(auth.uid(),es.estate_id,dt.id,dt.price,'pending',false,'DOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20))) returning * into existing; return jsonb_build_object('payment_id',existing.id,'amount',existing.amount,'status',existing.status,'reference',existing.reference,'documentation_type_id',dt.id,'documentation_name',dt.name,'already_created',false); end; $$; revoke all on function public.create_documentation_payment_request(uuid) from public; grant execute on function public.create_documentation_payment_request(uuid) to authenticated;
